// Oráculo: enumera cada índice atual removível e agrega apenas sequências mínimas.
map<string,pair<int,long long>> memo;
function<pair<int,long long>(string)> bruto=[&](string s)->pair<int,long long>{
 auto it=memo.find(s);if(it!=memo.end())return it->second;
 bool alternada=true;for(int i=1;i<(int)s.size();++i)if(s[i]==s[i-1])alternada=false;
 if(alternada)return memo[s]={0,1};
 int minimo=1000000;long long qtd=0;
 for(int i=0;i<(int)s.size();++i){
  string proxima=s;proxima.erase(i,1);auto r=bruto(proxima);int custo=1+r.first;
  if(custo<minimo){minimo=custo;qtd=r.second;}
  else if(custo==minimo)qtd+=r.second;
 }
 return memo[s]={minimo,qtd};
};
for(int n=1;n<=8;++n)for(int mask=0;mask<(1<<n);++mask){
 string s;for(int i=0;i<n;++i)s+=char('0'+((mask>>i)&1));
 assert(alternarComContagem(s)==bruto(s));
}
