assert(construcaoOtima("RRRBRRRBR",7,2));
assert(construcaoOtima("RRRBRRBRR",7,2));
assert(!construcaoOtima("RRRRBRRBR",7,2));
assert(!construcaoOtima("RRRBRRRBX",7,2));
for(int n=3;n<=10;++n){
 map<int,int> otimo;
 vector<tuple<string,int,int>> saidas;
 for(int mask=0;mask<(1<<n);++mask){
  string s;int r=0,pico=0,run=0;char anterior='?';
  for(int i=0;i<n;++i){char c=(mask>>i&1)?'R':'B';s+=c;r+=(c=='R');
   run=(c==anterior?run+1:1);pico=max(pico,run);anterior=c;}
  int b=n-r;if(!(r>b && b>=1))continue;
  if(!otimo.count(r))otimo[r]=pico;else otimo[r]=min(otimo[r],pico);
  saidas.push_back({s,r,pico});
 }
 for(const auto& entrada:saidas){auto [s,r,pico]=entrada;
  assert(construcaoOtima(s,r,n-r)==(pico==otimo[r]));}
}

